import{_ as d,o,c as e,ag as r}from"./chunks/framework.DoUXNnsN.js";const b=JSON.parse('{"title":"Modbus功能码","description":"","frontmatter":{"title":"Modbus功能码","aliases":["功能码","Modbus异常码","异常响应","FC03","FC06","FC16"],"tags":["工业通信","Modbus"],"status":"ai-draft","sources":["https://en.wikipedia.org/wiki/Modbus","https://www.simplymodbus.ca/FC03.htm","https://www.simplymodbus.ca/FC16.htm","https://www.simplymodbus.ca/FC05.htm","https://docs.elipse.com.br/documents/en-us/driver/modbus/latest/modbus_appendix_max_limit_block_size.html","https://docs.chipkin.com/articles/modbus-function-code-deep-dive-fc01-fc06-fc15-fc16-fc23/","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":3},"headers":[],"relativePath":"70-工业通信与自动化/Modbus/Modbus功能码.md","filePath":"70-工业通信与自动化/Modbus/Modbus功能码.md"}'),a={name:"70-工业通信与自动化/Modbus/Modbus功能码.md"};function l(s,t,i,c,u,h){return o(),e("div",null,[...t[0]||(t[0]=[r('<blockquote><p>本篇是 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a> 入门路径的第 3 篇。读完你应该能：根据要做的事选对功能码；写出每种功能码的请求和响应；看到异常响应能说出原因；知道一次最多能读写多少。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>功能码是 Modbus 报文里的一个字节，告诉从站&quot;要做什么&quot;：读哪张表、写哪张表、读写一个还是多个。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus数据模型与地址">Modbus数据模型与地址</a>：知道四张表和地址从 0 开始。</li><li><a href="/Encyclopedia/10-计算机基础/数据表示/十六进制">十六进制</a>。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>主站和从站都需要统一的&quot;动词表&quot;，否则从站不知道请求里的两个数字是&quot;读几个&quot;还是&quot;写什么值&quot;。Modbus 用一个字节的功能码规定了这些动词，每个动词的后面跟什么参数、回应是什么格式，都是固定的。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="最常用的-8-个功能码" tabindex="-1">最常用的 8 个功能码 <a class="header-anchor" href="#最常用的-8-个功能码" aria-label="Permalink to &quot;最常用的 8 个功能码&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能码</th><th>十六进制</th><th>名称</th><th>对象</th><th>用途</th></tr></thead><tbody><tr><td>01</td><td>0x01</td><td>读线圈</td><td>线圈</td><td>读开关输出的状态</td></tr><tr><td>02</td><td>0x02</td><td>读离散输入</td><td>离散输入</td><td>读开关/传感器的通断</td></tr><tr><td>03</td><td>0x03</td><td>读保持寄存器</td><td>保持寄存器</td><td>读设定值、配置，也常用来读测量值</td></tr><tr><td>04</td><td>0x04</td><td>读输入寄存器</td><td>输入寄存器</td><td>读测量值</td></tr><tr><td>05</td><td>0x05</td><td>写单个线圈</td><td>线圈</td><td>开/关一个输出</td></tr><tr><td>06</td><td>0x06</td><td>写单个寄存器</td><td>保持寄存器</td><td>改一个设定值</td></tr><tr><td>15</td><td>0x0F</td><td>写多个线圈</td><td>线圈</td><td>一次写一批开关</td></tr><tr><td>16</td><td>0x10</td><td>写多个寄存器</td><td>保持寄存器</td><td>一次写一批设定值</td></tr></tbody></table><p>此外还有 07、08、11、12、17、20–24、43 等不常用的，初学可以先不管。<strong>选择指南</strong>：看数据用 03/04；改设定值用 06/16；开关输出用 01/05/15。</p><h3 id="每个功能码的请求与响应" tabindex="-1">每个功能码的请求与响应 <a class="header-anchor" href="#每个功能码的请求与响应" aria-label="Permalink to &quot;每个功能码的请求与响应&quot;">​</a></h3><p>下面的 <code>地址</code> 都是<strong>线上地址</strong>（从 0 开始）。每个字段的长度写在括号里，单位字节。多字节数字都是<strong>高字节在前</strong>。为了突出重点，省略了前面的从站地址和后面的 CRC（RTU）或 MBAP 头（TCP），这部分叫 PDU。</p><p><strong>功能码 03 / 04（读寄存器，格式相同）</strong></p><ul><li>请求：功能码(1) + 起始地址(2) + 寄存器数量(2)</li><li>响应：功能码(1) + 字节数(1) + 数据（每个寄存器 2 字节）</li><li>例子（simplymodbus.ca，完整 RTU 帧）：请求 <code>11 03 006B 0003 7687</code>，响应 <code>11 03 06 AE41 5652 4340 49AD</code>，读 17 号从站从地址 107 开始的 3 个寄存器，字节数 06 = 3 × 2。</li></ul><p><strong>功能码 01 / 02（读位，格式相同）</strong></p><ul><li>请求：功能码(1) + 起始地址(2) + 位数量(2)</li><li>响应：功能码(1) + 字节数(1) + 状态位。<strong>8 个位打包进 1 个字节，第一个位放在字节的最低位</strong>，不足 8 位的用 0 补齐。</li><li>例子（我自己构造并算了 CRC）：读 1 号从站从线圈 0 开始的 10 个线圈。请求 <code>01 01 0000 000A BC0D</code>（CRC 线上顺序：<code>BC 0D</code>）。假设线圈 0、2、3、8 为 1，其余为 0，则第一个字节是二进制 <code>0000 1101</code> = <code>0x0D</code>（线圈 0 在最低位，线圈 3 在第 3 位），第二个字节只有线圈 8 为 1，是 <code>0x01</code>。响应 <code>01 01 02 0D 01 7C AC</code>。</li></ul><p><strong>功能码 05（写单个线圈）</strong></p><ul><li>请求：功能码(1) + 线圈地址(2) + 值(2)，<strong>值只有两种：<code>FF 00</code> 表示开，<code>00 00</code> 表示关</strong>，别的值不合法。</li><li>响应：请求的原样回显。</li><li>例子（simplymodbus.ca）：<code>11 05 00AC FF00 4E8B</code>，把 17 号从站的线圈 172（即&quot;线圈 #173&quot;）置为开，从站原样回这 8 个字节。</li></ul><p><strong>功能码 06（写单个寄存器）</strong></p><ul><li>请求：功能码(1) + 寄存器地址(2) + 值(2)</li><li>响应：请求的原样回显。</li><li>例子（我自己构造并算了 CRC）：把 1 号从站的寄存器 0 写成 100（<code>0x0064</code>）：<code>01 06 0000 0064 8821</code>（CRC 线上顺序：<code>88 21</code>）。</li></ul><p><strong>功能码 15（写多个线圈）</strong></p><ul><li>请求：功能码(1) + 起始地址(2) + 数量(2) + 字节数(1) + 位数据（和功能码 01 一样打包）</li><li>响应：功能码(1) + 起始地址(2) + 数量(2)</li></ul><p><strong>功能码 16（写多个寄存器）</strong></p><ul><li>请求：功能码(1) + 起始地址(2) + 数量(2) + 字节数(1) + 数据（每个寄存器 2 字节）</li><li>响应：功能码(1) + 起始地址(2) + 数量(2)</li><li>例子（simplymodbus.ca）：请求 <code>11 10 0001 0002 04 000A 0102 C6F0</code>：从地址 1 开始写 2 个寄存器，数据共 4 字节，值是 <code>000A</code>（=10）和 <code>0102</code>（=258）；响应 <code>11 10 0001 0002 1298</code>。</li></ul><h3 id="一次最多读写多少" tabindex="-1">一次最多读写多少 <a class="header-anchor" href="#一次最多读写多少" aria-label="Permalink to &quot;一次最多读写多少&quot;">​</a></h3><p>整个 PDU 最长 253 字节（功能码 1 字节 + 最多 252 字节数据），所以每种功能码有数量上限：</p><table tabindex="0"><thead><tr><th>功能码</th><th>数量上限</th></tr></thead><tbody><tr><td>01 / 02 读位</td><td>2000 个</td></tr><tr><td>03 / 04 读寄存器</td><td>125 个</td></tr><tr><td>15 写多个线圈</td><td>1968 个</td></tr><tr><td>16 写多个寄存器</td><td>123 个</td></tr></tbody></table><p>这些是协议的上限。<strong>有的设备或软件会设得更低</strong>，超限时可能不报错而是悄悄失败，所以批量读写时先按手册的限制来。（上限数字来自几份二手技术资料的互相印证，规范原文未逐字核对。）</p><h3 id="异常响应-从站-拒绝-时怎么说" tabindex="-1">异常响应：从站&quot;拒绝&quot;时怎么说 <a class="header-anchor" href="#异常响应-从站-拒绝-时怎么说" aria-label="Permalink to &quot;异常响应：从站&quot;拒绝&quot;时怎么说&quot;">​</a></h3><p>从站收到一个<strong>格式正确但做不了</strong>的请求时，回的不是正常响应，而是：</p><ul><li><strong>功能码 = 原功能码 + 0x80</strong>（最高位置 1）</li><li>后面跟 <strong>1 个字节的异常码</strong></li></ul><table tabindex="0"><thead><tr><th>异常码</th><th>名称</th><th>通俗含义</th><th>最常见的原因</th></tr></thead><tbody><tr><td>01</td><td>非法功能</td><td>我不支持这个功能码</td><td>用了设备不支持的功能码，例如设备不让用 04</td></tr><tr><td>02</td><td>非法数据地址</td><td>你说的地址我没有</td><td>地址超范围，或&quot;40001&quot;差 1 的换算错误</td></tr><tr><td>03</td><td>非法数据值</td><td>你给的数量或值不合规</td><td>数量为 0 或超过上限，写入值非法</td></tr><tr><td>04</td><td>从站设备故障</td><td>我处理时出故障了</td><td>设备内部错误</td></tr><tr><td>05</td><td>确认</td><td>我收到了，正在处理，需要时间</td><td>长时间任务</td></tr><tr><td>06</td><td>从站设备忙</td><td>我在忙，请稍后再试</td><td>设备正在处理别的</td></tr><tr><td>07</td><td>否定确认</td><td>无法执行这个编程操作</td><td>少见</td></tr><tr><td>08</td><td>存储奇偶校验错误</td><td>我的存储器自检出错</td><td>少见</td></tr><tr><td>10</td><td>网关路径不可用</td><td>网关找不到去目标设备的路</td><td>网关配置错</td></tr><tr><td>11</td><td>网关目标设备无响应</td><td>网关找到路但目标没回应</td><td>目标设备掉线</td></tr></tbody></table><p>例子：主站读一个不存在的地址，请求 <code>01 03 0064 0001</code>（读地址 100），从站回应 <code>01 83 02 C0F1</code>：<code>83</code> = <code>03</code> + <code>80</code>，<code>02</code> = 非法数据地址（CRC 线上顺序 <code>C0 F1</code>）。</p><p><strong>非常重要的区别</strong>：如果是<strong>传输出错</strong>（RTU 的 CRC 校验不对，或者帧不完整），从站<strong>根本不回应</strong>，主站只能等到超时。所以：</p><ul><li>收到异常响应 = 通信是通的，只是请求内容有问题，看异常码就能定位；</li><li>完全没有回应 = 通信层有问题（线、参数、地址、网络），需要排查链路。</li></ul><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因与办法</th></tr></thead><tbody><tr><td>03 能读，04 报异常码 1</td><td>设备只把数据放在保持寄存器里，换成 03</td></tr><tr><td>写 05 时报异常码 3</td><td>值不是 <code>FF00</code> 或 <code>0000</code></td></tr><tr><td>批量读 200 个寄存器报异常码 3</td><td>超过 125 个上限，拆成多次读</td></tr><tr><td>写多个寄存器没反应</td><td>字节数字段不等于&quot;数量 × 2&quot;，或者数量超 123</td></tr><tr><td>读一整块数据的某一格报异常码 2</td><td>整块范围里有设备没定义的地址，设备常常整个请求都拒绝，缩小范围逐段试</td></tr><tr><td>写成功但值过一会儿又变了</td><td>设备本身在更新这个寄存器，或者这个寄存器其实是只读映射</td></tr></tbody></table><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>写出读取 1 号从站线圈 0–7（共 8 个）的 PDU（不含地址和 CRC）。 <strong>答</strong>：<code>01 0000 0008</code>。</li><li>一个功能码 01 的响应数据字节是 <code>0xA5</code>，二进制 <code>1010 0101</code>，请问线圈 0 到线圈 7 依次是什么状态？ <strong>答</strong>：第一个线圈在最低位，从低位往高位读：1、0、1、0、0、1、0、1。即线圈 0=1，线圈 1=0，线圈 2=1，线圈 3=0，线圈 4=0，线圈 5=1，线圈 6=0，线圈 7=1。</li><li>主站向 5 号从站写寄存器 10，值为 300（<code>0x012C</code>），用功能码 06。写出 PDU，以及正常的响应。 <strong>答</strong>：PDU 是 <code>06 000A 012C</code>；正常响应是原样回显 <code>06 000A 012C</code>。</li><li>主站发 <code>03 0000 007E</code>，从站回异常。是哪个异常码最可能？ <strong>答</strong>：<code>0x7E</code> = 126，超过读寄存器的 125 个上限，最可能是异常码 3（非法数据值）。</li><li>从站回 <code>01 86 01 ...</code>，主站发的是什么？为什么出错？ <strong>答</strong>：<code>0x86</code> − <code>0x80</code> = <code>0x06</code>，是写单个寄存器；异常码 1 = 非法功能，该设备不支持用 06 写，可能要改用 16 写多个寄存器。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>功能码决定动作：读用 01/02/03/04，写用 05/06/15/16。</li><li>请求和响应格式固定：读位和读寄存器的响应都有&quot;字节数&quot;，位是打包的，最低位在前。</li><li>数量有上限：读 125 个寄存器、写 123 个寄存器、读 2000 位、写 1968 位。</li><li>异常响应 = 功能码 + 0x80 + 异常码；异常码 1/2/3 最常见；没有任何回应则是链路问题。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus数据模型与地址">Modbus数据模型与地址</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-RTU">Modbus-RTU</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a>、<a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Simply Modbus 写多个寄存器：<a href="https://www.simplymodbus.ca/FC16.htm" target="_blank" rel="noreferrer">https://www.simplymodbus.ca/FC16.htm</a></li><li>Simply Modbus 写单个线圈：<a href="https://www.simplymodbus.ca/FC05.htm" target="_blank" rel="noreferrer">https://www.simplymodbus.ca/FC05.htm</a></li><li>各功能码数量上限的汇总：<a href="https://docs.elipse.com.br/documents/en-us/driver/modbus/latest/modbus_appendix_max_limit_block_size.html" target="_blank" rel="noreferrer">https://docs.elipse.com.br/documents/en-us/driver/modbus/latest/modbus_appendix_max_limit_block_size.html</a></li></ul>',46)])])}const p=d(a,[["render",l]]);export{b as __pageData,p as default};
